// Guard the request boundary before spending anything on the LLM.
const wh = $('Webhook: Invoice Intake').first().json;
const cfg = $('Policy Config').first().json;
const body = wh.body ?? {};

const errors = [];
const source = typeof body.source === 'string' ? body.source.trim() : '';
const rawText = typeof body.invoiceText === 'string' ? body.invoiceText : '';
const invoiceText = rawText.trim();

if (!source) {
  errors.push('Field "source" is required and must be a non-empty string.');
}
if (!invoiceText) {
  errors.push('Field "invoiceText" is required and must be a non-empty string.');
} else if (invoiceText.length < cfg.minInvoiceTextLength) {
  errors.push(`Field "invoiceText" must be at least ${cfg.minInvoiceTextLength} characters to be worth extracting (got ${invoiceText.length}).`);
}

const headers = wh.headers ?? {};
const proto = headers['x-forwarded-proto'] || 'http';
const host = headers.host || 'localhost:5678';

return [{ json: {
  requestValid: errors.length === 0,
  requestErrors: errors,
  source,
  invoiceText,
  receivedAt: new Date().toISOString(),
  approvalBaseUrl: `${proto}://${host}/webhook/${cfg.approvalWebhookPath}`,
  policy: {
    approvalThresholdAmount: cfg.approvalThresholdAmount,
    minConfidence: cfg.minConfidence,
    amountTolerance: cfg.amountTolerance,
    maxInvoiceAgeDays: cfg.maxInvoiceAgeDays,
    minInvoiceTextLength: cfg.minInvoiceTextLength,
    approverInbox: cfg.approverInbox,
  },
} }];

// Coerce whatever the model produced into the pipeline's own types and derive the
// deterministic dedupe key. Nothing is judged here - that is the validator's job.
const src = $('Normalize Intake').first().json;
const raw = $json;

const carry = {
  source: src.source,
  invoiceText: src.invoiceText,
  policy: src.policy,
  approvalBaseUrl: src.approvalBaseUrl,
  receivedAt: src.receivedAt,
};

if (raw.error) {
  return [{ json: { ...carry, extractionOk: false, extractionError: String(raw.error) } }];
}

const x = raw.output ?? {};

const num = (v) => {
  if (typeof v === 'number') return Number.isFinite(v) ? Math.round(v * 100) / 100 : null;
  const n = parseFloat(String(v ?? '').replace(/[^0-9.eE+-]/g, ''));
  return Number.isFinite(n) ? Math.round(n * 100) / 100 : null;
};
const str = (v) => (v == null ? '' : String(v).trim());

const lineItems = Array.isArray(x.lineItems)
  ? x.lineItems.map((li) => ({
      desc: str(li && li.desc),
      qty: num(li && li.qty),
      unitPrice: num(li && li.unitPrice),
      total: num(li && li.total),
    }))
  : [];

const vendor = str(x.vendor);
const invoiceNumber = str(x.invoiceNumber);
const keyOf = (s) => s.toUpperCase().replace(/[^A-Z0-9]+/g, '-').replace(/^-+|-+$/g, '');
const invoiceId = vendor && invoiceNumber ? `${keyOf(vendor)}::${keyOf(invoiceNumber)}` : '';

let confidence = num(x.confidence);
if (confidence === null) confidence = 0;
if (confidence > 1) confidence = Math.min(confidence / 100, 1);
if (confidence < 0) confidence = 0;

// The model id lives only on the OpenRouter node; read it back for the audit trail
// instead of repeating the literal here.
let extractionModel = 'unknown';
try {
  extractionModel = $('OpenRouter Chat Model').params.model || 'unknown';
} catch (e) {
  extractionModel = 'unknown';
}

return [{ json: {
  ...carry,
  extractionOk: true,
  extractionError: null,
  invoiceId,
  vendor,
  invoiceNumber,
  invoiceDate: str(x.date),
  dueDate: str(x.dueDate),
  currency: str(x.currency).toUpperCase() || 'USD',
  lineItems,
  lineItemCount: lineItems.length,
  subtotal: num(x.subtotal),
  tax: num(x.tax),
  total: num(x.total),
  confidence,
  extractionModel,
} }];

// Re-derive every number the model reported. The invoice is trusted only if its
// own arithmetic holds.
const d = $json;
const p = d.policy;
const tol = p.amountTolerance;
const errors = [];
const r2 = (n) => Math.round(n * 100) / 100;

for (const [name, v] of [['vendor', d.vendor], ['invoiceNumber', d.invoiceNumber],
                         ['invoiceDate', d.invoiceDate], ['currency', d.currency]]) {
  if (!v) errors.push(`Required field "${name}" is missing from the extracted invoice.`);
}
for (const name of ['subtotal', 'tax', 'total']) {
  if (d[name] === null || d[name] === undefined) {
    errors.push(`Required amount "${name}" could not be read from the invoice.`);
  }
}
if (!d.lineItems.length) errors.push('No line items could be read from the invoice.');

d.lineItems.forEach((li, i) => {
  const n = i + 1;
  if (!li.desc) errors.push(`Line item ${n} has no description.`);
  if (li.qty === null || li.unitPrice === null || li.total === null) {
    errors.push(`Line item ${n} has amounts that could not be read as numbers.`);
    return;
  }
  const expected = r2(li.qty * li.unitPrice);
  if (Math.abs(expected - li.total) > tol) {
    errors.push(`Line item ${n} ("${li.desc}") is billed at ${li.total} but ${li.qty} x ${li.unitPrice} = ${expected}.`);
  }
});

if (d.subtotal !== null && d.lineItems.length) {
  const sum = r2(d.lineItems.reduce((a, li) => a + (li.total || 0), 0));
  if (Math.abs(sum - d.subtotal) > tol) {
    errors.push(`Line items sum to ${sum} but the invoice states a subtotal of ${d.subtotal} (tolerance ${tol}).`);
  }
}
if (d.subtotal !== null && d.tax !== null && d.total !== null) {
  const expected = r2(d.subtotal + d.tax);
  if (Math.abs(expected - d.total) > tol) {
    errors.push(`Invoice total ${d.total} does not equal subtotal ${d.subtotal} + tax ${d.tax} = ${expected}.`);
  }
}
if (d.total !== null && d.total <= 0) errors.push(`Invoice total ${d.total} must be greater than zero.`);
if (d.tax !== null && d.tax < 0) errors.push(`Tax ${d.tax} cannot be negative.`);

const parse = (s) => { const t = Date.parse(s); return Number.isNaN(t) ? null : new Date(t); };
const now = new Date();
const inv = parse(d.invoiceDate);
if (d.invoiceDate && !inv) errors.push(`Invoice date "${d.invoiceDate}" is not a valid date.`);
if (inv) {
  const ageDays = Math.floor((now - inv) / 86400000);
  if (ageDays < -1) errors.push(`Invoice date ${d.invoiceDate} is in the future.`);
  if (ageDays > p.maxInvoiceAgeDays) {
    errors.push(`Invoice date ${d.invoiceDate} is ${ageDays} days old, outside the ${p.maxInvoiceAgeDays}-day intake window.`);
  }
}
const due = parse(d.dueDate);
if (d.dueDate && !due) errors.push(`Due date "${d.dueDate}" is not a valid date.`);
if (inv && due && due < inv) errors.push(`Due date ${d.dueDate} is before the invoice date ${d.invoiceDate}.`);

if (!d.invoiceId) {
  errors.push('Could not derive a dedupe key: vendor or invoiceNumber is missing.');
}

return [{ json: { ...d, invoiceValid: errors.length === 0, validationErrors: errors } }];

// A Data Table "get" with no match emits a single empty item (alwaysOutputData is on),
// so presence is decided by the system column `id`, never by item count.
const d = $('Validate Invoice').first().json;
const hits = (name) => $(name).all()
  .filter((i) => i.json && i.json.id !== undefined && i.json.id !== null);

const ledgerHits = hits('Lookup: Ledger Duplicate');
const pendingHits = hits('Lookup: Pending Duplicate');

const isDuplicate = ledgerHits.length > 0 || pendingHits.length > 0;
const duplicateOf = ledgerHits.length ? 'ap_ledger' : (pendingHits.length ? 'ap_pending' : null);
const match = ledgerHits.length ? ledgerHits[0].json : (pendingHits.length ? pendingHits[0].json : null);

return [{ json: {
  ...d,
  isDuplicate,
  duplicateOf,
  existingRowId: match ? String(match.id) : null,
  existingStatus: ledgerHits.length ? 'posted' : (match ? (match.status ?? null) : null),
} }];

const d = $json;
const p = d.policy;
const reasons = [];
if (d.total > p.approvalThresholdAmount) {
  reasons.push(`Invoice total ${d.currency} ${d.total} exceeds the ${d.currency} ${p.approvalThresholdAmount} auto-approval threshold.`);
}
if (d.confidence < p.minConfidence) {
  reasons.push(`Extraction confidence ${d.confidence} is below the ${p.minConfidence} auto-approval floor.`);
}
if (!reasons.length) reasons.push('Held by approval policy.');

return [{ json: {
  ...d,
  status: 'pending',
  holdReasons: reasons,
  holdReasonsJson: JSON.stringify(reasons),
  lineItemsJson: JSON.stringify(d.lineItems),
  queuedAt: new Date().toISOString(),
  approveUrl: d.approvalBaseUrl,
  approverInbox: p.approverInbox,
} }];

// The ledger sink refused the write even after retries. The invoice must not be
// lost and the caller must not be told it was posted.
let p = null;
try { p = $('Build Ledger Payload (Auto)').first().json; } catch (e) { p = null; }
if (!p) { try { p = $('Build Ledger Payload (Approved)').first().json; } catch (e) { p = null; } }
if (!p) p = {};

const rawErr = $json && ($json.error || $json.message);
const errText = !rawErr ? 'The ledger adapter failed and returned no detail.'
  : (typeof rawErr === 'string' ? rawErr : (rawErr.message || JSON.stringify(rawErr)));

const reasons = [
  'The ledger sink rejected the write after all retries, so this invoice was NOT posted.',
  `Adapter error: ${errText}`,
  `Approval path at the time of failure: ${p.approvalPath || 'unknown'}.`,
];

return [{ json: {
  invoiceId: p.invoiceId || `UNPOSTED::${$execution.id}`,
  stage: 'ledger_unavailable',
  vendor: p.vendor || '',
  invoiceNumber: p.invoiceNumber || '',
  total: p.total === null || p.total === undefined ? 0 : p.total,
  reasons: JSON.stringify(reasons),
  confidence: p.confidence === null || p.confidence === undefined ? 0 : p.confidence,
  source: p.source || '',
  rawExcerpt: `Ledger write failed for invoice ${p.invoiceNumber || 'unknown'} from ${p.vendor || 'unknown vendor'}.`,
} }];

const d = $json;
const reasons = [
  'The language model could not turn this text into a structured invoice.',
  `Extractor error: ${d.extractionError}`,
];
return [{ json: {
  invoiceId: `UNPARSED::${$execution.id}`,
  stage: 'extraction',
  vendor: '',
  invoiceNumber: '',
  total: 0,
  reasons: JSON.stringify(reasons),
  confidence: 0,
  source: d.source,
  rawExcerpt: String(d.invoiceText || '').slice(0, 500),
} }];

const d = $json;
return [{ json: {
  invoiceId: d.invoiceId || `UNPARSED::${$execution.id}`,
  stage: 'validation',
  vendor: d.vendor,
  invoiceNumber: d.invoiceNumber,
  total: d.total === null || d.total === undefined ? 0 : d.total,
  reasons: JSON.stringify(d.validationErrors),
  confidence: d.confidence,
  source: d.source,
  rawExcerpt: String(d.invoiceText || '').slice(0, 500),
} }];

const wh = $('Webhook: Invoice Approve').first().json;
const body = wh.body ?? {};
const errors = [];

const invoiceId = typeof body.invoiceId === 'string' ? body.invoiceId.trim() : '';
const rawDecision = typeof body.decision === 'string' ? body.decision.trim().toLowerCase() : '';
const approver = typeof body.approver === 'string' ? body.approver.trim() : '';
const note = typeof body.note === 'string' ? body.note.trim() : '';

if (!invoiceId) errors.push('Field "invoiceId" is required.');
if (!approver) errors.push('Field "approver" is required so the decision is attributable.');
if (!rawDecision) {
  errors.push('Field "decision" is required.');
} else if (!['approve', 'approved', 'reject', 'rejected'].includes(rawDecision)) {
  errors.push(`Field "decision" must be "approve" or "reject" (got "${body.decision}").`);
}

const decision = rawDecision.startsWith('approve') ? 'approve'
  : (rawDecision.startsWith('reject') ? 'reject' : '');

return [{ json: {
  decisionValid: errors.length === 0,
  decisionErrors: errors,
  invoiceId, decision, approver, note,
  decidedAt: new Date().toISOString(),
} }];

const d = $('Normalize Decision').first().json;
const hits = $('Lookup: Pending Invoice').all()
  .filter((i) => i.json && i.json.id !== undefined && i.json.id !== null);
const row = hits.length ? hits[0].json : null;

return [{ json: {
  ...d,
  found: row !== null,
  pendingRowId: row ? String(row.id) : null,
  currentStatus: row ? row.status : null,
  alreadyDecided: row ? row.status !== 'pending' : false,
  priorApprover: row ? (row.approver || null) : null,
  priorDecidedAt: row ? (row.decidedAt || null) : null,
  invoice: row,
} }];

const d = $json;
const r = d.invoice;
let count = 0;
try { count = JSON.parse(r.lineItems || '[]').length; } catch (e) { count = 0; }

return [{ json: {
  invoiceId: r.invoiceId,
  vendor: r.vendor,
  invoiceNumber: r.invoiceNumber,
  invoiceDate: r.invoiceDate,
  dueDate: r.dueDate,
  currency: r.currency,
  subtotal: r.subtotal,
  tax: r.tax,
  total: r.total,
  lineItems: r.lineItems,
  lineItemCount: count,
  confidence: r.confidence,
  approvalPath: 'manual',
  approver: d.approver,
  source: r.source,
  extractionModel: r.extractionModel || 'unknown',
  intakeExecutionId: String($execution.id),
} }];

const d = $json;
const r = d.invoice;
const reasons = [`Rejected by ${d.approver} at ${d.decidedAt}.`];
if (d.note) reasons.push(`Approver note: ${d.note}`);
try {
  for (const h of JSON.parse(r.holdReasons || '[]')) reasons.push(`Originally held because: ${h}`);
} catch (e) {
  // holdReasons was not valid JSON; the rejection reason above still stands.
}

return [{ json: {
  invoiceId: r.invoiceId,
  stage: 'approval_rejected',
  vendor: r.vendor,
  invoiceNumber: r.invoiceNumber,
  total: r.total,
  reasons: JSON.stringify(reasons),
  confidence: r.confidence,
  source: r.source,
  rawExcerpt: `Invoice ${r.invoiceNumber} from ${r.vendor} was rejected at the approval gate and was never posted to the ledger.`,
} }];
